-- MCQ question bank and auto-graded online quizzes. Safe to run more than once.
CREATE TABLE IF NOT EXISTS "McqQuestion" ("id" TEXT PRIMARY KEY, "chairmanId" TEXT NOT NULL, "courseCode" TEXT NOT NULL, "stem" TEXT NOT NULL, "optionsJson" TEXT NOT NULL, "correct" INTEGER NOT NULL, "cloCode" TEXT, "topic" TEXT, "difficulty" TEXT NOT NULL DEFAULT 'MEDIUM', "bloom" TEXT, "explanation" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "McqQuestion_chairmanId_courseCode_idx" ON "McqQuestion" ("chairmanId", "courseCode");
CREATE TABLE IF NOT EXISTS "OnlineQuiz" ("id" TEXT PRIMARY KEY, "courseId" TEXT NOT NULL, "instrumentId" TEXT, "title" TEXT NOT NULL, "opensAt" TIMESTAMP(3) NOT NULL, "closesAt" TIMESTAMP(3) NOT NULL, "durationMin" INTEGER NOT NULL DEFAULT 20, "pickJson" TEXT NOT NULL, "shuffle" BOOLEAN NOT NULL DEFAULT true, "showResults" BOOLEAN NOT NULL DEFAULT true, "negativePct" DOUBLE PRECISION NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'DRAFT', "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "OnlineQuiz_courseId_idx" ON "OnlineQuiz" ("courseId");
CREATE TABLE IF NOT EXISTS "QuizAttempt" ("id" TEXT PRIMARY KEY, "quizId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "questionIdsJson" TEXT NOT NULL, "orderJson" TEXT NOT NULL DEFAULT '{}', "answersJson" TEXT NOT NULL DEFAULT '{}', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "submittedAt" TIMESTAMP(3), "score" DOUBLE PRECISION, "maxScore" DOUBLE PRECISION, "perCloJson" TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS "QuizAttempt_quizId_studentId_key" ON "QuizAttempt" ("quizId", "studentId");
SELECT 'done' AS result;
